const clone=o=>JSON.parse(JSON.stringify(o));let data;try{data=JSON.parse(localStorage.getItem('adastra_demo_v2'))||clone(defaultData)}catch{data=clone(defaultData)};
let state={role:'',page:'Home / Landing Page',modal:'',search:'',selectedJob:1,menu:false};
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Prototype intentionally never stores passwords or collects real IP addresses.
function normalizeDemoUsers(){data.users.forEach((u,i)=>{u.id??=i+1;u.email??=([ 'applicant@brightwave.demo','nicole@brightwave.demo','hr@brightwave.demo','patricia@brightwave.demo','it@brightwave.demo'][i]||`user${i+1}@brightwave.demo`);u.passwordState??='Reset not requested';u.lastLogin??='Not recorded';u.lastIp??='Unavailable (offline prototype)';delete u.password;delete u.temporaryPassword;});}
normalizeDemoUsers();
const save=()=>localStorage.setItem('adastra_demo_v2',JSON.stringify(data));
const toast=msg=>{let t=$('toast');t.textContent=msg;t.style.display='block';clearTimeout(window._toast);window._toast=setTimeout(()=>t.style.display='none',3300)};
const id=()=>Date.now()+Math.floor(Math.random()*1000);
const audit=action=>{data.audit.unshift({action,by:ROLE_NAMES[state.role]||'Guest',time:new Date().toLocaleString('en-PH')});save()};
const badge=s=>{let c=/approved|complete|hired|active|open|accepted|passed/i.test(s)?'green':/reject|not selected|overdue|inactive|failed/i.test(s)?'red':/pending|progress|screen|scheduled|review|interview|assessment/i.test(s)?'orange':'gray';return `<span class="pill ${c}">${esc(s)}</span>`};
const btn=(label,action,variant='secondary')=>`<button class="btn ${variant}" onclick="${action}">${label}</button>`;
const field=(label,name,value='',type='text',required=true)=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`;
const textarea=(label,name,value='')=>`<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}">${esc(value)}</textarea></div>`;
const select=(label,name,options,selected='')=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(o=>`<option ${o===selected?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}" class="empty">No records match your search.</td></tr>`}</tbody></table></div>`;
const panel=(title,body,action='')=>`<section class="panel"><div class="toolbar"><h3>${title}</h3>${action}</div>${body}</section>`;
const stats=items=>`<div class="stat-grid">${items.map(([v,l])=>`<div class="stat"><span>${l}</span><strong>${v}</strong><div class="progress"><div style="width:${Math.min(100,Number.parseInt(v)||55)}%"></div></div></div>`).join('')}</div>`;
const chart=()=>`<div class="mini-chart">${[48,64,57,82,74,95].map((h,i)=>`<div style="height:${h}%"><span>${['May','Jun','Jul','Aug','Sep','Oct'][i]}</span></div>`).join('')}</div><p class="hint" style="margin-top:30px">Illustrative onboarding completion trend · Demo data</p>`;
const filterRows=rows=>rows.filter(r=>JSON.stringify(r).toLowerCase().includes(state.search.toLowerCase()));
const searchBar=()=>`<input class="search" aria-label="Search table" placeholder="Search records..." value="${esc(state.search)}" oninput="searchTable(this.value)">`;
function searchTable(v){state.search=v;let body=$('dynamic-table');if(body)body.innerHTML=state.page==='Recruitment Management'?jobTable():state.page==='Applicant Management'?applicationTable():'';}
function listing(heads,rowsFn,action=''){window._tableRender=()=>table(heads,rowsFn(filterRows(window._sourceRows||[])));return `<div class="toolbar">${searchBar()}${action}</div><div id="dynamic-table">${window._tableRender()}</div>`}
const progress=()=>Math.round(data.tasks.filter(t=>t.done).length/data.tasks.length*100);
const logo=()=>`<img class="brand-img" src="${LOGO}" alt="BrightWave Digital Services, Inc. official logo">`;
// Authentication is enforced by Supabase. The local demo records are fictional and not shared.
let authUser=null,authReady=false;
let serverUsers=[],usersLoading=false,usersError='';
const authClient=(()=>{
 const cfg=window.HRIMS_SUPABASE||{};
 if(!cfg.url||!cfg.publishableKey||cfg.publishableKey.includes('PASTE_')||!window.supabase)return null;
 return window.supabase.createClient(cfg.url,cfg.publishableKey);
})();
function roleFromUser(user){const role=user?.app_metadata?.hrims_role;return Object.prototype.hasOwnProperty.call(ROLE_NAMES,role)?role:null}
function authenticatedRole(){return authUser?roleFromUser(authUser):null}
function navigate(page,role=state.role){
 if(role==='it' && ['User Account Management','Credential & Login Activity','Password Reset & Account Provisioning'].includes(page))loadServerUsers();
 const assigned=authenticatedRole();
 if(role && (!assigned||role!==assigned)){state.role='';state.page='Applicant Login';render();toast('Sign in with an authorized account to access this portal.');return}
 if(!role && assigned && NAV[assigned].includes(page))role=assigned;
 state.role=role||'';state.page=page;state.search='';state.menu=false;
 render();window.scrollTo(0,0);
}
function login(role){if(!authenticatedRole()||role!==authenticatedRole()){navigate('Applicant Login','');return}navigate(NAV[role][role==='applicant'?6:role==='employee'?1:0],role)}
async function logout(){if(authClient)await authClient.auth.signOut();authUser=null;state.role='';state.page='Home / Landing Page';state.modal='';render()}
async function initializeAuth(){
 if(!authClient){authReady=true;render();return}
 try{const {data:{session}}=await authClient.auth.getSession();authUser=session?.user||null;
 if(authUser&&authenticatedRole())login(authenticatedRole());
 else if(authUser){state.page='Applicant Login';render()}
 authClient.auth.onAuthStateChange((_event,session)=>{
 const prior=authUser?.id;authUser=session?.user||null;
 if(!authUser){state.role='';state.page='Applicant Login';state.modal='';render()}
 else if(!prior&&authenticatedRole())login(authenticatedRole());
 });
 }catch(err){console.error('Authentication initialization failed',err)}
 authReady=true;render();
}
function publicHeader(){return `<header class="site-header">${logo()}<nav class="nav-links"><a href="#" onclick="navigate('Home / Landing Page','');return false">Home</a><a href="#" onclick="navigate('About Us','');return false">About Us</a><a href="#" onclick="navigate('Careers / Job Openings','');return false">Careers</a></nav><div class="nav-actions">${btn('Log in',"navigate('Applicant Login','')",'outline')}${btn('Get started',"navigate('Applicant Registration','')")}</div></header>`}
function home(){return `<div class="hero"><div><div class="eyebrow">Welcome to BrightWave Digital Services, Inc.</div><h1>Smarter Solutions.<br><span style="color:#08aebd">Meaningful Connections.</span></h1><p>Empowering people, connecting opportunities, and building a future-ready workforce through digital innovation. Explore careers and experience our Ad Astra HRIMS.</p><div class="flex" style="margin-top:25px">${btn('Explore Open Positions →',"navigate('Careers / Job Openings','')")}${btn('Sign in to HRIMS',"navigate('Applicant Login','')",'outline')}</div><p class="hint">Angeles City, Pampanga, Philippines · BPO · Customer Support · Digital Services</p></div><div class="hero-art"><div class="window"><div class="flex" style="justify-content:space-between"><strong>Ad Astra HRIMS</strong><span class="pill green">System ready</span></div><h2 style="font-size:35px;margin:20px 0 0;color:#073b78">90-day onboarding</h2><p class="muted">One connected experience for every employee.</p><div class="progress"><div style="width:73%"></div></div><div class="mock-row"></div><div class="mock-row"></div><div class="mock-row"></div><div class="grid two" style="margin-top:20px"><div class="card"><strong>5</strong><p>Connected portals</p></div><div class="card"><strong>24/7</strong><p>Digital access</p></div></div></div></div></div><section class="section"><span class="eyebrow">What we do</span><h2>Digital services with people at the center.</h2><div class="grid">${[['☏','Customer Support','Human-centered customer experiences across communication channels.'],['◈','Business Process Outsourcing','Flexible operational support and business process solutions.'],['▤','Digital Services','Technology-enabled workflows, marketing and digital operations.']].map(([i,t,d])=>`<div class="card"><div class="icon-bubble">${i}</div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><section class="section"><div class="toolbar"><div><span class="eyebrow">Join our team</span><h2>Featured career opportunities</h2></div>${btn('All vacancies',"navigate('Careers / Job Openings','')")}</div><div class="grid">${data.jobs.slice(0,3).map(j=>jobCard(j)).join('')}</div></section>${footer()}`}
function footer(){return `<footer class="footer">© 2026 BrightWave Digital Services, Inc. · Angeles City, Pampanga · Ad Astra HRIMS — Interactive academic prototype. Not a live hiring website.</footer>`}
function about(){return `<section class="section"><span class="eyebrow">About BrightWave</span><h2>Building stronger connections through digital excellence.</h2><p class="muted">BrightWave Digital Services, Inc. is a simulated Philippine digital services company based in Angeles City, Pampanga. With an illustrative workforce of approximately 60 employees, we provide BPO, customer support and digital services while championing people-centered innovation.</p><div class="grid" style="margin-top:25px">${[['Our Mission','Deliver reliable digital services while empowering employees with modern tools, continuous learning, and meaningful work.'],['Our Vision','Be a trusted digital services partner recognized for operational excellence and an inclusive, future-ready workforce.'],['Our Values','Integrity · Collaboration · Innovation · Accountability · Empathy · Continuous Improvement']].map(([t,d])=>`<div class="card"><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><div class="panel" style="margin-top:20px"><h3>Our Story</h3><p>BrightWave is a fictional company created for an HR modernization project. Its Ad Astra 90-Day Onboarding Support Program demonstrates how a small HR team can standardize onboarding, support hybrid employees, and make data-informed decisions.</p><p><strong>Industry:</strong> Business Process Outsourcing, Customer Support & Digital Services<br><strong>Location:</strong> Angeles City, Pampanga, Philippines<br><strong>Workforce:</strong> Approximately 60 employees</p></div></section>${footer()}`}
function jobCard(j){return `<article class="card"><div class="flex" style="justify-content:space-between"><span class="pill">${esc(j.department)}</span>${badge(j.status)}</div><h3 style="margin-top:18px">${esc(j.title)}</h3><p>${esc(j.description)}</p><p class="hint">⌖ ${esc(j.location)} · ${esc(j.type)}</p><strong>${esc(j.salary)}</strong><div style="margin-top:18px">${btn('View Details →',`viewJob(${j.id})`)}</div></article>`}
function viewJob(i){state.selectedJob=i;navigate('Job Details','')}
function careers(){return `<section class="section"><div class="toolbar"><div><span class="eyebrow">Careers at BrightWave</span><h2>Find your next opportunity</h2><p class="muted">Explore roles in customer support, digital services and business operations.</p></div><input class="search" placeholder="Search job titles..." aria-label="Search vacancies" oninput="document.querySelectorAll('.job-tile').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(this.value.toLowerCase()))"></div><div class="grid">${data.jobs.filter(j=>j.status==='Open').map(j=>`<div class="job-tile">${jobCard(j)}</div>`).join('')}</div></section>${footer()}`}
function jobDetails(){let j=data.jobs.find(x=>x.id===state.selectedJob)||data.jobs[0];return `<section class="section"><button class="btn outline sm" onclick="navigate('Careers / Job Openings','')">← Back to Careers</button><div class="panel" style="margin-top:20px"><span class="pill">${esc(j.department)}</span><h1>${esc(j.title)}</h1><p class="muted">${esc(j.location)} · ${esc(j.type)} · ${esc(j.salary)}</p><div class="divider"></div><h3>Position Overview</h3><p>${esc(j.description)}</p><h3>Key Responsibilities</h3><p>Collaborate with your team, deliver high-quality work, maintain service standards, and follow company policies.</p><h3>Qualifications</h3><p>${esc(j.requirements)}</p><h3>Benefits</h3><p>Statutory benefits as applicable, learning opportunities, structured onboarding, and company-approved flexible work arrangements.</p><h3>How to apply</h3><p>Create an applicant account and submit your application with an updated resume.</p>${btn('Apply for this role →',`applyJob(${j.id})`)}</div></section>${footer()}`}
function applyJob(i){state.selectedJob=i;if(state.role==='applicant')navigate('Job Application Form','applicant');else navigate('Applicant Registration','')}
function authPage(reg=false){
 const cfgOk=!!authClient;
 return `<div class="auth-wrap"><div class="auth-card">${logo()}<h2>${reg?'Create applicant account':'Welcome back'}</h2><p class="muted">${reg?'Register as an Applicant. Other roles are assigned by an administrator.':'Sign in with your Supabase email and password. Your assigned role determines your portal.'}</p>
 ${!cfgOk?'<p class="auth-error">Supabase is not configured yet. Open supabase-config.js and enter your project URL and publishable key.</p>':''}
 ${authUser&&!authenticatedRole()?'<p class="auth-error">Your account has no assigned HRIMS role. Contact the administrator.</p>':''}
 <form onsubmit="${reg?'registerApplicant(event)':'signIn(event)'}">
 ${reg?field('Full name','name'):''}${field('Email address','email','','email')}${field('Password','password','','password')}
 <button class="btn" style="width:100%;margin-top:12px" ${!cfgOk?'disabled':''}>${reg?'Create applicant account':'Sign in →'}</button></form>
 <p class="hint" style="text-align:center">${reg?'Already have an account?':'New applicant?'} <a style="color:var(--blue)" href="#" onclick="navigate('${reg?'Applicant Login':'Applicant Registration'}','');return false">${reg?'Sign in':'Register here'}</a></p>
 <div class="divider"></div><p class="hint">Academic demonstration only. Use fictional HR records. All five dashboards require an authenticated account with a trusted assigned role.</p></div></div>`;
}
async function registerApplicant(e){
 e.preventDefault();if(!authClient)return toast('Configure Supabase first');
 const f=new FormData(e.target),email=String(f.get('email')).trim(),password=String(f.get('password'));
 const {data:result,error}=await authClient.auth.signUp({email,password,options:{data:{full_name:String(f.get('name')).trim()}}});
 if(error)return toast(error.message);
 if(result.session){toast('Applicant account created. Role provisioning may take a moment.');await authClient.auth.refreshSession()}
 else toast('Registration submitted. Check your email for a confirmation link, then sign in.');
 navigate('Applicant Login','');
}
async function signIn(e){
 e.preventDefault();if(!authClient)return toast('Configure Supabase first');
 const f=new FormData(e.target),button=e.target.querySelector('button[type=submit],button.btn');
 if(button)button.disabled=true;
 try{const {data:result,error}=await authClient.auth.signInWithPassword({email:String(f.get('email')).trim(),password:String(f.get('password'))});
 if(error)return toast(error.message);
 authUser=result.user;
 const role=authenticatedRole();if(!role){state.role='';state.page='Applicant Login';render();return toast('Signed in, but no HRIMS role is assigned. Contact the administrator.')}
 login(role);
 }finally{if(button&&button.isConnected)button.disabled=false}
}
function shell(){let role=state.role,nav=NAV[role];return `<div class="menu-overlay ${state.menu?'open':''}" onclick="toggleMenu()"></div><div class="shell"><aside class="sidebar ${state.menu?'open':''}">${logo()}<div class="portal-label">${ROLE_NAMES[role]} Portal</div><div class="side-items">${nav.map((p,i)=>`<button class="side-item ${p===state.page?'active':''}" onclick="navigate('${p.replace(/'/g,"\\'")}','${role}')"><span class="sym">${ICONS[i%ICONS.length]}</span><span>${esc(p)}</span></button>`).join('')}</div><div class="divider"></div><button class="side-item" onclick="logout()">⇥ &nbsp; Sign out</button></aside><div class="main"><header class="topbar"><div class="flex"><button class="btn outline sm mobile-menu" onclick="toggleMenu()">☰ Menu</button><strong>Ad Astra <span style="color:var(--blue)">HRIMS</span></strong><span class="pill">Prototype</span></div><div class="flex"><button class="btn outline sm" onclick="logout()">⇥ Sign out</button><button class="btn outline sm" onclick="navigate('${role==='employee'?'Notifications & Reminders':'Notifications'}','${role}')">♧</button><span class="pill">${ROLE_NAMES[role]}</span></div></header><main class="content"><div class="page-head"><div><div class="breadcrumb">BrightWave / ${ROLE_NAMES[role]} / ${esc(state.page)}</div><h1>${esc(state.page)}</h1><div class="muted">${subtitle(role,state.page)}</div></div><div class="flex">${btn('Export CSV',"exportCurrent()",'outline sm')}${btn('Quick actions',"openModal('quickActions')",'secondary sm')}</div></div>${portalContent(role,state.page)}</main></div></div>`}
function toggleMenu(){state.menu=!state.menu;render()}
function subtitle(role,p){return p.includes('Dashboard')?'A real-time overview of your demo workspace.':p.includes('Onboarding')?'Ad Astra 90-Day Onboarding Support Program.':`Manage ${p.toLowerCase()} through your ${ROLE_NAMES[role].toLowerCase()} workspace.`}
function render(){let app=$('app');if(state.role!==authenticatedRole())state.role='';if(!state.role){app.innerHTML=publicHeader()+(state.page==='About Us'?about():state.page==='Careers / Job Openings'?careers():state.page==='Job Details'?jobDetails():state.page==='Applicant Registration'?authPage(true):state.page==='Applicant Login'?authPage(false):home())}else{if(!NAV[state.role]?.includes(state.page))state.page=NAV[state.role][0];app.innerHTML=shell()}if(state.modal)app.insertAdjacentHTML('beforeend',modalHTML())}
function openModal(type,extra=''){state.modal=type;state.modalExtra=extra;render()}
function closeModal(){state.modal='';render()}
function modalHTML(){let type=state.modal;let inner='';if(type==='rolePicker')inner=`<h3>Role access</h3><p>Your role is assigned to your authenticated account. To switch accounts, sign out and sign in with another account.</p>${btn('Sign out',"state.modal='';logout()")}`;
else if(type==='quickActions')inner=`<h3>Quick actions</h3><div class="stack">${(state.role==='hr'?[['Post vacancy','Recruitment Management'],['Review applicants','Applicant Management'],['View onboarding','Onboarding Management']]:state.role==='employee'?[['My checklist','Onboarding Checklist'],['HR help desk','HR Help Desk'],['30-day check-in','30-Day Check-In']]:state.role==='it'?[['Manage users','User Account Management'],['View audit logs','Security & Audit Logs']]:[['View dashboard',NAV[state.role][0]],['View notifications',NAV[state.role].at(-1)]]).map(([label,page])=>btn(label,`state.modal='';navigate('${page}','${state.role}')`,'outline')).join('')}</div>`;
else if(type==='job')inner=`<h3>Post a job opening</h3><form onsubmit="submitRecord(event,'jobs')">${field('Job title','title')}${field('Department','department')}${select('Work arrangement','type',['Hybrid','Remote','On-site'])}${field('Salary range','salary')}${textarea('Job description','description')}${textarea('Qualifications','requirements')}<button class="btn">Publish vacancy</button></form>`;
else if(type==='employee')inner=`<h3>Add employee</h3><form onsubmit="submitRecord(event,'employees')">${field('Full name','name')}${field('Position','role')}${field('Department','department')}${field('Supervisor','supervisor')}<button class="btn">Add employee</button></form>`;
else if(type==='announcement')inner=`<h3>Publish announcement</h3><form onsubmit="submitRecord(event,'announcements')">${field('Title','title')}${textarea('Announcement','body')}<button class="btn">Publish announcement</button></form>`;
else if(type==='interview')inner=`<h3>Schedule interview</h3><form onsubmit="submitRecord(event,'interviews')">${select('Applicant','applicant',data.applications.map(a=>a.name))}${field('Job position','job')}${field('Date','date','','date')}${field('Time','time','','time')}${select('Mode','mode',['Video Interview','On-site Interview','Phone Interview'])}<button class="btn">Schedule</button></form>`;
else if(type==='assessment')inner=`<h3>Assign assessment</h3><form onsubmit="submitRecord(event,'assessments')">${select('Applicant','applicant',data.applications.map(a=>a.name))}${field('Assessment title','title')}<button class="btn">Assign</button></form>`;
else if(type==='offer')inner=`<h3>Create job offer</h3><form onsubmit="submitRecord(event,'offers')">${select('Applicant','applicant',data.applications.map(a=>a.name))}${select('Job','job',data.jobs.map(j=>j.title))}${field('Monthly salary','salary')}<button class="btn">Create offer</button></form>`;
else if(type==='ticket')inner=`<h3>Submit a support request</h3><form onsubmit="submitRecord(event,'tickets')">${field('Subject','subject')}${select('Support team','type',['HR','IT'])}${textarea('Describe your concern','detail')}<button class="btn">Submit request</button></form>`;
else if(type==='training')inner=`<h3>Assign training</h3><form onsubmit="submitRecord(event,'training')">${field('Training title','title')}${field('Estimated duration','duration')}<button class="btn">Assign training</button></form>`;
else if(type==='task')inner=`<h3>Add onboarding task</h3><form onsubmit="submitRecord(event,'tasks')">${field('Task description','title')}${select('Milestone','stage',['30','60','90'])}<button class="btn">Add task</button></form>`;
else if(type==='user')inner=`<h3>Add user account</h3><p class="muted">Create a real Supabase account. Use a unique temporary password and share it privately with the intended user.</p><form onsubmit="createITUser(event)">${field('Full name','name')}${field('Email address','email','','email')}${select('Assigned role','role',Object.keys(ROLE_NAMES))}${field('Temporary password (12+ characters)','password','','password')}<button class="btn">Create account</button></form>`;
else if(type==='passwordReset')inner=`<h3>Set a new password</h3><p>Account: <strong>${esc(serverUsers.find(u=>u.id===state.modalExtra)?.email||'Unknown')}</strong></p><p class="muted">Passwords cannot be viewed or recovered. IT can assign a new temporary password through the secure server function. Share it privately, never publish it on the dashboard.</p><form onsubmit="setITPassword(event)">${field('New password (12+ characters)','password','','password')}<button class="btn">Update password</button></form>`;
else if(type==='support')inner=`<h3>Refer employee for support</h3><form onsubmit="submitRecord(event,'tickets')">${select('Employee','owner',data.employees.map(e=>e.name))}${field('Concern','subject')}${textarea('Recommended support','detail')}<button class="btn">Send to HR</button></form>`;
else if(type==='note')inner=`<h3>Record performance feedback</h3><form onsubmit="submitRecord(event,'feedback')">${select('Employee','owner',data.employees.map(e=>e.name))}${select('Rating','rating',['Excellent','Meets Expectations','Needs Support'])}${textarea('Feedback and development recommendations','comments')}<button class="btn">Save feedback</button></form>`;
else if(type==='reset')inner=`<h3>Reset demo data?</h3><p>This clears all changes saved in this browser and restores the original sample records.</p>${btn('Cancel','closeModal()','outline')}&nbsp;${btn('Reset all sample data','resetDemo()','danger')}`;
return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(type)}"><div class="modal-head"><span class="eyebrow">Ad Astra HRIMS</span><button class="close" onclick="closeModal()" aria-label="Close dialog">✕</button></div>${inner}</div></div>`}
function submitRecord(e,kind){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.id=id();if(kind==='jobs'){o.location='Angeles City, Pampanga';o.status='Open'}if(kind==='employees'){o.id='BW-'+Math.floor(Math.random()*900+100);o.day=1;o.progress=0;o.status='Active'}if(kind==='tickets'){o.owner=o.owner||data.profile.name;o.status='Open'}if(kind==='tasks'){o.done=false;o.stage=Number(o.stage)}if(kind==='announcements')o.date=new Date().toISOString().slice(0,10);if(kind==='interviews')o.status='Scheduled';if(kind==='assessments')Object.assign(o,{status:'Assigned',score:'—'});if(kind==='offers')o.status='Pending';if(kind==='training')o.status='Not Started';if(kind==='users')o.status='Active';data[kind].unshift(o);audit('Created '+kind+' record');state.modal='';render();toast('Record saved in this browser')}
function update(kind,i,key,value){let x=data[kind].find(a=>String(a.id)===String(i));if(x){x[key]=value;audit(`Updated ${kind}: ${key}`);render();toast('Updated successfully')}}
function resetDemo(){data=clone(defaultData);save();state.modal='';render();toast('Demo data restored')}
function exportCurrent(){let keys=Object.keys(data).filter(k=>Array.isArray(data[k]));let k=state.page.includes('Applicant')?'applications':state.page.includes('Recruit')||state.page.includes('Job')?'jobs':state.page.includes('Document')?'documents':state.page.includes('Ticket')||state.page.includes('Help Desk')?'tickets':state.page.includes('Feedback')?'feedback':state.page.includes('Training')?'training':state.page.includes('Check')?'checkins':'employees';if(!keys.includes(k))k='employees';let arr=data[k];if(!arr.length){toast('No records available to export');return}let cols=Object.keys(arr[0]),csv=[cols.join(','),...arr.map(o=>cols.map(c=>'"'+String(o[c]??'').replaceAll('"','""')+'"').join(','))].join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`adastra-${k}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast('CSV exported')}
function dashboard(role){if(role==='applicant')return stats([['1','My applications'],['2','Open vacancies'],['1','Upcoming interview'],['3','Notifications']])+`<div class="split">${panel('Application progress',table(['Position','Status','Next step'],data.applications.slice(0,2).map(a=>[esc(a.job),badge(a.status),'Check your tracker'])),btn('View tracker',"navigate('Application Status Tracker','applicant')"))}${panel('Recent announcements',announcements())}</div>`;
if(role==='employee')return stats([[progress()+'%','Onboarding complete'],[data.tasks.filter(t=>!t.done).length,'Pending tasks'],['43','Day of onboarding'],['2','Upcoming activities']])+`<div class="split">${panel('Your onboarding journey',`<p class="muted">Day 43 of 90 · Welcome, ${esc(data.profile.name)}</p><div class="progress"><div style="width:${progress()}%"></div></div><div class="divider"></div>${data.tasks.slice(0,5).map(t=>`<div class="list-row"><span>${t.done?'✓':'○'} ${esc(t.title)}</span>${badge(t.done?'Complete':'Pending')}</div>`).join('')}`,btn('Open checklist',"navigate('Onboarding Checklist','employee')"))}${panel('Upcoming milestones',`<div class="timeline">${[['Day 30','Initial check-in and adjustment review'],['Day 60','Progress review and support'],['Day 90','Final onboarding evaluation']].map(([t,d])=>`<div class="timeline-item"><h4>${t}</h4><p>${d}</p></div>`).join('')}</div>`)}</div>`;
if(role==='hr')return stats([['60','Total workforce (simulated)'],[data.applications.length,'Applicants in pipeline'],[data.employees.length,'New hires monitored'],[data.documents.filter(d=>d.status!=='Approved').length,'Documents needing review']])+`<div class="split">${panel('Recruitment pipeline',table(['Applicant','Position','Stage'],data.applications.map(a=>[esc(a.name),esc(a.job),badge(a.status)])),btn('Manage applicants',"navigate('Applicant Management','hr')"))}${panel('Onboarding performance',chart())}</div>`;
if(role==='supervisor')return stats([[data.employees.length,'Assigned new hires'],['2','Scheduled check-ins'],['3','Training activities'],['1','Support requests']])+`<div class="split">${panel('My team',employeeTable())}${panel('Upcoming check-ins',scheduleList())}</div>`;
return stats([[data.users.length,'Demo user accounts'],['5','Role groups'],['99.9%','Illustrative uptime'],[data.tickets.filter(t=>t.type==='IT'&&t.status!=='Resolved').length,'IT support tickets']])+`<div class="split">${panel('System overview',`<div class="list-row">Application ${badge('Demo Running')}</div><div class="list-row">Browser storage ${badge('Active')}</div><div class="list-row">Real server connection ${badge('Not Connected')}</div><div class="list-row">Email gateway ${badge('Simulation Only')}</div><p class="hint">System metrics are illustrative, not actual infrastructure telemetry.</p>`)}${panel('Recent activity',auditList())}</div>`}
function announcements(){return data.announcements.map(a=>`<div class="list-row"><div><strong>${esc(a.title)}</strong><p class="muted" style="margin:4px 0">${esc(a.body)}</p></div><span class="hint">${esc(a.date)}</span></div>`).join('')}
function auditList(){return data.audit.slice(0,6).map(a=>`<div class="list-row"><div><strong>${esc(a.action)}</strong><div class="hint">${esc(a.by)}</div></div><span class="hint">${esc(a.time)}</span></div>`).join('')}
function employeeTable(){return table(['Employee','Position','Onboarding','Status'],data.employees.map(e=>[esc(e.name),esc(e.role),`${e.progress}% · Day ${e.day}`,badge(e.status)]))}
function applicationTable(){return table(['Applicant','Job opening','Applied','Stage','Action'],filterRows(data.applications).map(a=>[esc(a.name),esc(a.job),esc(a.date),`<select aria-label="Application status for ${esc(a.name)}" onchange="update('applications',${a.id},'status',this.value)">${['Applied','Screening','Interview','Assessment','Final Review','Hired','Not Selected'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select>`,btn('Review',`toast('Application ${a.id} selected for review')`,'outline sm')]))}
function jobTable(){return table(['Position','Department','Work mode','Salary','Status','Action'],filterRows(data.jobs).map(j=>[esc(j.title),esc(j.department),esc(j.type),esc(j.salary),badge(j.status),btn(j.status==='Open'?'Close':'Reopen',`update('jobs',${j.id},'status','${j.status==='Open'?'Closed':'Open'}')`,'outline sm')]))}
function docsTable(hr=false){return table(['Requirement','Employee','File name','Status','Action'],filterRows(data.documents).map(d=>[esc(d.name),esc(d.owner),esc(d.file),badge(d.status),hr?`<div class="flex">${btn('Approve',`update('documents',${d.id},'status','Approved')`,'secondary sm')}${btn('Reject',`update('documents',${d.id},'status','Rejected')`,'danger sm')}</div>`:esc(d.status)]))}
function ticketTable(admin=false,type=''){return table(['ID','Request','Owner','Type','Status','Action'],filterRows(data.tickets.filter(t=>!type||t.type===type)).map(t=>[`#${t.id}`,esc(t.subject),esc(t.owner),badge(t.type),badge(t.status),admin?btn('Resolve',`update('tickets',${t.id},'status','Resolved')`,'secondary sm'):btn('View',`toast(${JSON.stringify(t.detail)})`,'outline sm')]))}
function checklist(){return `<div class="split">${panel('My onboarding requirements',`<p class="muted">Mark completed activities as you progress. Changes are saved locally in this demo.</p>${data.tasks.map(t=>`<label class="check"><input type="checkbox" ${t.done?'checked':''} onchange="toggleTask(${t.id},this.checked)"><span style="flex:1">${esc(t.title)}</span><span class="pill">Day ${t.stage}</span></label>`).join('')}`)}${panel('Completion summary',`<h1 style="font-size:50px;color:var(--navy)">${progress()}%</h1><div class="progress"><div style="width:${progress()}%"></div></div><p>${data.tasks.filter(t=>t.done).length} of ${data.tasks.length} tasks completed</p><div class="divider"></div><p class="muted">Your assigned checklist spans three onboarding milestones. HR verifies official employment requirements separately.</p>`)}</div>`}
function toggleTask(i,v){let t=data.tasks.find(t=>t.id===i);if(t){t.done=v;audit('Updated onboarding checklist');render();toast('Checklist updated')}}
function profilePage(role){let p=role==='applicant'?data.applicantProfile:data.profile;return `<div class="split">${panel('Personal information',`<form onsubmit="saveProfile(event,'${role}')">${field('Full name','name',p.name)}${field('Email address','email',p.email,'email')}${field('Mobile number','phone',p.phone)}${field('Education','education',p.education)}${textarea('Skills','skills',p.skills)}${textarea('Work experience','experience',p.experience)}<button class="btn">Save profile</button></form>`)}${panel('Employment details',role==='employee'?`<div class="list-row"><strong>Employee ID</strong> BW-001</div><div class="list-row"><strong>Position</strong> Customer Support Specialist</div><div class="list-row"><strong>Department</strong> Customer Experience</div><div class="list-row"><strong>Supervisor</strong> Patricia Garcia</div><div class="list-row"><strong>Work arrangement</strong> Hybrid</div>`:`<p class="muted">Complete your profile before submitting a job application.</p><p>${badge('Applicant account')}</p>`)}</div>`}
function saveProfile(e,role){e.preventDefault();data[role==='applicant'?'applicantProfile':'profile']=Object.fromEntries(new FormData(e.target));audit('Updated profile');toast('Profile updated')}
function applicationForm(){return panel('Submit a job application',`<form onsubmit="submitApplication(event)">${field('Full name','name',data.applicantProfile.name)}${field('Email','email',data.applicantProfile.email,'email')}${select('Position','job',data.jobs.filter(j=>j.status==='Open').map(j=>j.title),data.jobs.find(j=>j.id===state.selectedJob)?.title)}${textarea('Cover letter / motivation','message')}<div class="field"><label>Resume (prototype: filename only)</label><input type="file" name="resume" accept=".pdf,.doc,.docx"><p class="hint">The browser demo does not upload or securely store the file itself.</p></div><button class="btn">Submit application</button></form>`)}
function submitApplication(e){e.preventDefault();let f=new FormData(e.target);data.applications.unshift({id:id(),name:f.get('name'),email:f.get('email'),job:f.get('job'),status:'Applied',date:new Date().toISOString().slice(0,10)});audit('Submitted job application');navigate('Application Status Tracker','applicant');toast('Application submitted in demo mode')}
function uploadPage(role){return `<div class="split">${panel('Submit a document',`<form onsubmit="submitDocument(event)">${select('Document type','name',['Valid Government ID','Employment Contract','BIR Form 1902','SSS / PhilHealth / Pag-IBIG information','Resume','Other supporting document'])}<div class="field"><label>Choose a file</label><input type="file" id="upload-file" required accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"><span class="hint">Demo stores only the filename, not document bytes. Do not upload real personal records.</span></div><button class="btn">Submit document</button></form>`)}${panel('Document submission status',docsTable(false))}</div>`}
function submitDocument(e){e.preventDefault();let f=new FormData(e.target),file=$('upload-file').files[0];if(!file)return toast('Select a file');data.documents.unshift({id:id(),name:f.get('name'),owner:state.role==='applicant'?data.applicantProfile.name:data.profile.name,status:'Submitted',file:file.name});audit('Submitted document metadata');render();toast('Document filename recorded (demo only)')}
function statusTracker(){let a=data.applications.at(0);let steps=['Applied','Screening','Interview','Assessment','Final Review','Hired'];let pos=steps.indexOf(a?.status||'Applied');return `<div class="split">${panel('My application status',`<h3>${esc(a?.job||'No applications yet')}</h3><p>${badge(a?.status||'Not started')}</p><div class="timeline">${steps.map((s,i)=>`<div class="timeline-item"><h4 style="color:${i<=pos?'#087de1':'#899baa'}">${s} ${i<=pos?'✓':''}</h4><p>${i<=pos?'Stage reached':'Upcoming stage'}</p></div>`).join('')}</div><p class="hint">Recruitment stages are illustrative. The HR team controls the actual stage in this demo.</p>`)}${panel('Submitted applications',table(['Job','Date','Status'],data.applications.map(a=>[esc(a.job),esc(a.date),badge(a.status)])))}</div>`}
function scheduleList(){return data.interviews.map(i=>`<div class="list-row"><div><strong>${esc(i.applicant)}</strong><p class="muted" style="margin:0">${esc(i.job)} · ${esc(i.mode)}</p></div><span class="pill">${esc(i.date)} ${esc(i.time)}</span></div>`).join('')||'<p class="muted">No upcoming events.</p>'}
function interviewsPage(admin=false){return panel(admin?'Interview management':'My interview schedule',table(['Applicant','Position','Date','Time','Mode','Status'],data.interviews.map(i=>[esc(i.applicant),esc(i.job),esc(i.date),esc(i.time),esc(i.mode),badge(i.status)])),admin?btn('+ Schedule interview',"openModal('interview')"):'')}
function assessmentsPage(admin=false){return panel(admin?'Assessment management':'Assigned assessments',table(['Applicant','Assessment','Status','Result'],data.assessments.map(a=>[esc(a.applicant),esc(a.title),badge(a.status),esc(a.score)])),admin?btn('+ Assign assessment',"openModal('assessment')"):'')}
function offersPage(admin=false){return panel(admin?'Job offer management':'My job offers',table(['Applicant','Position','Monthly salary','Status','Action'],data.offers.map(o=>[esc(o.applicant),esc(o.job),esc(o.salary),badge(o.status),admin?btn('Mark sent',`update('offers',${o.id},'status','Sent')`,'outline sm'):`${btn('Accept',`update('offers',${o.id},'status','Accepted')`,'secondary sm')} ${btn('Decline',`update('offers',${o.id},'status','Declined')`,'danger sm')}`])) ,admin?btn('+ Create offer',"openModal('offer')"):'')}
function onboardingPlan(){return `<div class="grid">${[[30,'Days 1–30','Orientation & foundation',['Welcome orientation','Company handbook','Employee documentation','Initial training','30-day check-in']],[60,'Days 31–60','Integration & development',['Role-specific training','Supervisor coaching','Employee feedback','60-day check-in']],[90,'Days 61–90','Confidence & evaluation',['Performance feedback','Satisfaction survey','Final documentation','90-day check-in']]].map(([day,title,sub,items])=>`<div class="card"><span class="pill">Milestone ${day}</span><h3 style="margin-top:12px">${title}</h3><p>${sub}</p><div class="divider"></div>${items.map(x=>`<div class="list-row"><span>✓ ${x}</span></div>`).join('')}</div>`).join('')}</div>`}
function checkinPage(day,admin=false){return `<div class="split">${panel(`${day}-day check-in`,`<p class="muted">${day===30?'Initial adjustment and orientation':day===60?'Training progress and development':'Final onboarding experience'} review.</p><form onsubmit="submitCheckin(event,${day})">${admin?select('Employee','owner',data.employees.map(e=>e.name)):''}${select('How is onboarding going?','rating',['Very well','Well','Needs some support','Need urgent assistance'])}${textarea('Progress, concerns, or observations','comments')}<button class="btn">Submit ${day}-day review</button></form>`)}${panel('Recorded check-ins',table(['Milestone','Employee','Rating','Date'],data.checkins.filter(c=>admin||c.day===day).map(c=>[`Day ${c.day}`,esc(c.owner),badge(c.rating),esc(c.date)])))}</div>`}
function submitCheckin(e,day){e.preventDefault();let f=new FormData(e.target);data.checkins.unshift({id:id(),day,owner:f.get('owner')||data.profile.name,rating:f.get('rating'),comments:f.get('comments'),date:new Date().toISOString().slice(0,10)});audit(`Recorded ${day}-day check-in`);render();toast('Check-in recorded')}
function feedbackPage(admin=false){return `<div class="split">${panel(admin?'Employee feedback responses':'Employee satisfaction survey',admin?table(['Employee','Rating','Comment'],data.feedback.map(f=>[esc(f.owner||'Anonymous'),badge(f.rating),esc(f.comments)])):`<form onsubmit="submitFeedback(event)">${select('Overall onboarding experience','rating',['Very satisfied','Satisfied','Neutral','Dissatisfied','Very dissatisfied'])}${textarea('What could we improve?','comments')}<button class="btn">Submit feedback</button></form>`)}${panel('Program feedback',`<p class="muted">Use employee feedback to improve clarity, training accessibility, communication and onboarding support.</p>${statsMini('85%','Illustrative satisfaction target')}`)}</div>`}
function submitFeedback(e){e.preventDefault();let f=new FormData(e.target);data.feedback.unshift({id:id(),owner:data.profile.name,rating:f.get('rating'),comments:f.get('comments')});audit('Submitted employee feedback');render();toast('Feedback submitted')}
function statsMini(n,l){return `<h1 style="font-size:40px;color:var(--navy)">${n}</h1><p class="muted">${l}</p>`}
function trainingPage(admin=false){return panel('Orientation & training',table(['Training','Duration','Status','Action'],data.training.map(t=>[esc(t.title),esc(t.duration),badge(t.status),admin?btn('Mark complete',`update('training',${t.id},'status','Complete')`,'outline sm'):btn('Complete',`update('training',${t.id},'status','Complete')`,'secondary sm')])),admin?btn('+ Assign training',"openModal('training')"):'')}
function handbook(admin=false){return `<div class="grid two">${[['Welcome to BrightWave','Company mission, vision, values and organizational structure.'],['Hybrid Work Guidelines','Expected availability, collaboration, confidentiality and equipment care.'],['Professional Conduct','Respect, anti-harassment, customer confidentiality and ethical conduct.'],['Information Security','Strong passwords, access controls, reporting incidents and secure data handling.'],['Employee Development','Training, performance feedback and continuous learning opportunities.'],['Leave & Statutory Benefits','Policies must follow applicable Philippine labor laws and company procedures.']].map(([t,d])=>`<div class="card"><span class="pill">Policy guide</span><h3 style="margin-top:12px">${t}</h3><p>${d}</p>${btn(admin?'Edit policy (demo)':'Read policy',`toast('Policy preview: ${t}')`,'outline sm')}</div>`).join('')}</div>`}
function supportPage(admin=false,type=''){return panel('Support requests',ticketTable(admin,type),btn(admin?'View all requests':'+ New support request',admin?"toast('Showing available support requests')":"openModal('ticket')"))}
function notificationsPage(admin=false){return `<div class="split">${panel('Notifications & reminders',data.notifications.map(n=>`<div class="list-row"><div><strong>◉ ${esc(n.text)}</strong><p class="hint">${esc(n.date)}</p></div>${badge('Info')}</div>`).join(''))}${panel('Company announcements',announcements(),admin?btn('+ Publish',"openModal('announcement')"):'')}</div>`}
function settingsPage(role){return `<div class="split">${panel('Account and system preferences',`<form onsubmit="saveSettings(event)">${field('Company name','company',data.settings.company)}${select('Data retention period (months)','retention',['12','24','36'],data.settings.retention)}<label class="check"><input type="checkbox" name="reminders" ${data.settings.reminders?'checked':''}>Enable demo reminders</label><label class="check"><input type="checkbox" name="mfa" ${data.settings.mfa?'checked':''}>MFA required (demo configuration only)</label><button class="btn">Save preferences</button></form>`)}${panel('Prototype controls',`<p class="muted">All data is saved in localStorage on this device. These controls do not configure real email, security or server infrastructure.</p>${btn('Restore original sample data',"openModal('reset')",'danger')}<div class="divider"></div><h3>Security notice</h3><p class="muted">Do not use real employee data or passwords. A production HRIMS requires a secure backend, authenticated sessions, protected storage, audit controls and privacy review.</p>`)}</div>`}
function saveSettings(e){e.preventDefault();let f=new FormData(e.target);data.settings={company:f.get('company'),retention:f.get('retention'),reminders:!!f.get('reminders'),mfa:!!f.get('mfa')};audit('Updated demo settings');toast('Preferences saved')}
function analytics(){return stats([['95%','Checklist target'],['90%','Check-in target'],['85%','Satisfaction target'],['20%','Admin time reduction target']])+`<div class="split">${panel('Illustrative monthly onboarding completion',chart())}${panel('Pilot program measurement',`<div class="list-row">Checklist completion <strong>${progress()}% (sample user)</strong></div><div class="list-row">Recorded check-ins <strong>${data.checkins.length}</strong></div><div class="list-row">Feedback submissions <strong>${data.feedback.length}</strong></div><div class="list-row">Documents approved <strong>${data.documents.filter(d=>d.status==='Approved').length}</strong></div><p class="hint">Targets are proposed. Real KPIs require baseline measurements and actual operational data.</p>`)}</div>`}
function genericRows(kind,columns,formatter){return table(columns,data[kind].map(formatter))}
