async function adminRequest(action,payload={}){
 if(!authClient||authenticatedRole()!=='it')throw Error('IT Administrator login required');
 const {data:{session},error}=await authClient.auth.getSession();
 if(error||!session)throw Error('Please sign in again');
 const cfg=window.HRIMS_SUPABASE;
 const res=await fetch(cfg.url+'/functions/v1/hrims-admin',{
  method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token,'apikey':cfg.publishableKey},
  body:JSON.stringify({action,...payload})
 });
 const out=await res.json().catch(()=>({error:'Invalid server response'}));
 if(!res.ok)throw Error(out.error||'Server request failed');
 return out;
}
async function loadServerUsers(){
 if(authenticatedRole()!=='it'||usersLoading)return;
 usersLoading=true;usersError='';
 try{const result=await adminRequest('list');serverUsers=result.users||[]}
 catch(err){usersError=err.message;serverUsers=[]}
 finally{usersLoading=false;if(state.role==='it'&&['User Account Management','Credential & Login Activity','Password Reset & Account Provisioning'].includes(state.page))render()}
}
function credentialDirectory(){
 const rows=serverUsers.map(u=>[esc(u.name||'—'),esc(u.email),badge(ROLE_NAMES[u.role]||u.role||'Unassigned'),'<span class="muted">Hidden (hashed)</span>',esc(u.last_sign_in_at?new Date(u.last_sign_in_at).toLocaleString():'Never'),badge(u.banned_until?'Disabled':'Active'),btn('Change password',`openModal('passwordReset','${esc(u.id)}')`,'outline sm')]);
 return `<div class="panel"><div class="toolbar"><div><h3>Supabase user accounts</h3><p class="muted">Real accounts from Supabase. Passwords are never shown. IT can create accounts and set new passwords.</p></div><div class="flex">${btn('Refresh',"loadServerUsers()",'outline sm')}${btn('+ Add account',"openModal('user')")}</div></div>${usersLoading?'<p>Loading accounts…</p>':''}${usersError?`<p class="auth-error">${esc(usersError)}. Deploy the hrims-admin Edge Function first.</p>`:''}${table(['Name','Email','Role','Password','Last sign-in','Status','Action'],rows)}<p class="hint">For academic demonstration only. Never publish demo passwords or use real employee records without further data protections.</p></div>`;
}
async function createITUser(e){
 e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim(),email=String(f.get('email')).trim().toLowerCase(),role=String(f.get('role')),password=String(f.get('password'));
 if(password.length<12)return toast('Use at least 12 characters');
 try{await adminRequest('create',{name,email,role,password});state.modal='';render();toast('Account created in Supabase');await loadServerUsers()}
 catch(err){toast(err.message)}
}
async function setITPassword(e){
 e.preventDefault();const password=String(new FormData(e.target).get('password'));
 if(password.length<12)return toast('Use at least 12 characters');
 try{await adminRequest('set_password',{user_id:state.modalExtra,password});state.modal='';render();toast('Password updated securely');await loadServerUsers()}
 catch(err){toast(err.message)}
}
function exportKind(k){if(!data[k].length)return toast('No records available');let cols=Object.keys(data[k][0]),csv=[cols.join(','),...data[k].map(o=>cols.map(c=>'"'+String(o[c]??'').replaceAll('"','""')+'"').join(','))].join('\r\n');downloadFile(csv,`adastra-${k}.csv`,'text/csv')}
function downloadFile(content,name,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('File downloaded')}
function backupJSON(){downloadFile(JSON.stringify(data,null,2),'adastra-demo-backup.json','application/json')}
function restoreJSON(input){let file=input.files[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let obj=JSON.parse(reader.result);if(!obj.jobs||!obj.employees||!obj.tasks)throw Error('Invalid backup structure');data=obj;normalizeDemoUsers();save();render();toast('Demo backup restored')}catch{toast('Invalid backup file')}};reader.readAsText(file)}
initializeAuth();
